<?php
declare(strict_types=1);
require_once __DIR__.'/../auth_check.php';AccessManager::requirePageAccess();
require_once __DIR__.'/../model/Database.php';require_once __DIR__.'/../services/ChantierFinancialComplianceService.php';
$pdo=Database::getConnection();$service=new ChantierFinancialComplianceService($pdo);$audit=$service->auditActive();
$rows=$pdo->query("SELECT c.id,c.code,c.titre,c.devis_id,c.financial_data_status,c.financial_data_checked_at,c.financial_data_issue,d.numero_devis,d.total_ttc,cl.nom_client FROM chantier_banamur c LEFT JOIN devis_banamur d ON d.id=c.devis_id LEFT JOIN client_banamur cl ON cl.id_client=c.client_id WHERE c.archived_at IS NULL ORDER BY (c.financial_data_status='compliant'),c.code,c.id")->fetchAll(PDO::FETCH_ASSOC)?:[];
function regularisationIssueAction(array $row,string $issue):array{
    $chantierId=(int)$row['id'];$devisId=(int)($row['devis_id']??0);$workshop='regularisation.php?id='.$chantierId;
    if(str_contains($issue,'Devis principal introuvable')||str_contains($issue,'non rattaché'))return['url'=>$workshop.'#atelier','label'=>'Rattacher le devis','icon'=>'fa-link','help'=>'Choisissez le devis principal correspondant à ce chantier.'];
    if(str_contains($issue,'Montant TTC')||str_contains($issue,'Aucune ligne dans le devis'))return['url'=>$devisId>0?'../devis/modifier.php?devisId='.$devisId.'#devis-lines':$workshop.'#correction-devis','label'=>'Corriger le devis','icon'=>'fa-file-pen','help'=>'Complétez les lignes, quantités et prix : les totaux seront recalculés.'];
    if(str_contains($issue,'Planning général'))return['url'=>$devisId>0?'../devis/planning.php?devisId='.$devisId.'#planning-devis':$workshop.'#atelier','label'=>'Compléter le planning','icon'=>'fa-calendar-days','help'=>'Renseignez des dates de début et de fin cohérentes pour le devis.'];
    if(str_contains($issue,'Échéancier')||str_contains($issue,'Date manquante dans'))return['url'=>$devisId>0?'../facturation/echeancier_devis.php?chantier_id='.$chantierId.'&devis_id='.$devisId.'#echeancier':$workshop.'#atelier','label'=>'Corriger la facturation','icon'=>'fa-file-invoice-dollar','help'=>'Définissez dans Facturation les dates et pourcentages d’encaissement jusqu’à 100 %.'];
    if(str_contains($issue,'Déboursé')||str_contains($issue,'déboursé'))return['url'=>$devisId>0?'../debourse/gerer_debourse.php?devisId='.$devisId.'#planning-debourse':$workshop.'#atelier','label'=>str_contains($issue,'Dates')?'Corriger les dates':'Gérer le déboursé','icon'=>'fa-coins','help'=>str_contains($issue,'Dates')?'Ouvrez les postes concernés et corrigez leurs dates de début et de fin.':'Rattachez, chiffrez et planifiez les déboursés dans la limite autorisée.'];
    return['url'=>$workshop.'#atelier','label'=>'Ouvrir la correction','icon'=>'fa-screwdriver-wrench','help'=>'Ouvrez l’atelier guidé pour compléter cette information.'];
}
if(($_GET['format']??'')==='csv'){header('Content-Type:text/csv; charset=utf-8');header('Content-Disposition:attachment; filename="rapport-regularisation-chantiers-'.date('Y-m-d').'.csv"');$out=fopen('php://output','wb');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['Code','Chantier','Client','Devis','Montant TTC','Statut','Corrections attendues','Contrôlé le'],';');foreach($rows as $r)fputcsv($out,[$r['code'],$r['titre'],$r['nom_client'],$r['numero_devis'],$r['total_ttc'],$r['financial_data_status'],$r['financial_data_issue'],$r['financial_data_checked_at']],';');fclose($out);exit;}
$pageTitle='Rapport de fiabilité des chantiers';$activeMenu='';require_once __DIR__.'/../decaissement/includes/header.php';require_once __DIR__.'/../decaissement/includes/navbar.php';
?>
