<main class="min-h-screen bg-slate-50 px-4 py-8"><div class="mx-auto max-w-7xl"><header class="rounded-3xl bg-slate-950 p-7 text-white"><p class="text-xs font-black uppercase tracking-[.2em] text-amber-300">FINEA · Rapport de contrôle</p><div class="mt-2 flex flex-wrap items-end justify-between gap-4"><div><h1 class="text-3xl font-black">Fiabilité des données des chantiers actifs</h1><p class="mt-2 text-slate-300">Les données restent incluses dans les statistiques. Ce rapport indique précisément les réserves à lever.</p></div><div class="flex flex-wrap gap-2 print:hidden"><a href="export_rapport_regularisation.php?format=xlsx" class="rounded-xl bg-emerald-600 px-4 py-3 font-bold"><i class="fas fa-file-excel mr-1"></i> Excel Finéa</a><a href="export_rapport_regularisation.php?format=pdf" class="rounded-xl bg-rose-600 px-4 py-3 font-bold"><i class="fas fa-file-pdf mr-1"></i> PDF Finéa</a></div></div></header>
<section class="mt-5 grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><article class="rounded-2xl bg-white p-5 shadow-sm"><small class="font-bold text-slate-500">Chantiers actifs</small><strong class="mt-2 block text-3xl"><?=(int)$audit['total']?></strong></article><article class="rounded-2xl border border-emerald-200 bg-emerald-50 p-5"><small class="font-bold text-emerald-700">Conformes</small><strong class="mt-2 block text-3xl text-emerald-900"><?=(int)$audit['compliant']?></strong></article><article class="rounded-2xl border border-amber-200 bg-amber-50 p-5"><small class="font-bold text-amber-700">À régulariser</small><strong class="mt-2 block text-3xl text-amber-900"><?=(int)$audit['incomplete']?></strong></article><article class="rounded-2xl bg-indigo-700 p-5 text-white"><small class="font-bold text-indigo-200">Fiabilité documentaire</small><strong class="mt-2 block text-3xl"><?=number_format($audit['total']?($audit['compliant']/$audit['total']*100):100,1,',',' ')?> %</strong></article></section>
<section class="mt-6 overflow-hidden rounded-2xl border bg-white shadow-sm"><div class="border-b p-5"><h2 class="text-xl font-black">Analyse chantier par chantier</h2><p class="text-sm text-slate-500">Chaque réserve conduit directement à l’écran et au bloc qui permettent de la corriger.</p></div><div class="divide-y"><?php foreach($rows as $r):$issues=array_values(array_filter(array_map('trim',explode('|',(string)$r['financial_data_issue']))));?><article class="grid gap-4 p-5 lg:grid-cols-[220px_1fr_150px]"><div><strong class="text-indigo-800"><?=htmlspecialchars((string)$r['code'])?></strong><h3 class="font-black text-slate-950"><?=htmlspecialchars((string)$r['titre'])?></h3><small class="text-slate-500"><?=htmlspecialchars((string)($r['nom_client']?:'Client non renseigné'))?></small></div><div><p class="text-sm font-bold text-slate-700"><?=htmlspecialchars((string)($r['numero_devis']?:'Devis non rattaché'))?> · <?=number_format((float)$r['total_ttc'],0,',',' ')?> FCFA</p><?php if($issues):?><?php foreach($issues as $issue):$action=regularisationIssueAction($r,$issue);?><div class="rr-issue"><span class="rr-issue-icon"><i class="fas fa-circle-exclamation"></i></span><div><strong><?=htmlspecialchars($issue)?></strong><small><?=htmlspecialchars($action['help'])?></small></div><a class="rr-cta print:hidden" href="<?=htmlspecialchars($action['url'])?>"><i class="fas <?=htmlspecialchars($action['icon'])?>"></i><?=htmlspecialchars($action['label'])?></a></div><?php endforeach;?><?php else:?><p class="mt-2 text-sm font-bold text-emerald-700"><i class="fas fa-circle-check mr-1"></i>Dossier complet</p><?php endif;?></div><div class="text-right"><span class="inline-flex rounded-full px-3 py-1 text-xs font-black <?=($r['financial_data_status']==='compliant')?'bg-emerald-100 text-emerald-800':'bg-amber-100 text-amber-900'?>"><?=($r['financial_data_status']==='compliant')?'CONFORME':'À RÉGULARISER'?></span><?php if($r['financial_data_status']!=='compliant'):?><a href="regularisation.php?id=<?=(int)$r['id']?>#atelier" class="mt-3 block text-sm font-bold text-indigo-700 print:hidden">Ouvrir tout le dossier →</a><?php endif;?></div></article><?php endforeach;?></div></section></div></main>
